    double bs_sine = 0.0, rs_sine = 0.0;
    int usable = 0;
    int fault = 0;
    unint32 n;

    n = qo_input.count;

    if ((qo_input.body == 0) || (qo_input.reference == 0) || (qo_input.weights == 0) ||
        (n < 2U) || (n > 3U)) {
        fault = 1;
    }
    if (!fault) {
        if ((!isfinite(qo_config.minimum_weight)) || (qo_config.minimum_weight <= 0.0) ||
            (!isfinite(qo_config.minimum_separation_sine)) ||
            (qo_config.minimum_separation_sine <= 0.0) ||
            (qo_config.minimum_separation_sine > 1.0) ||
            (qo_config.required_good < 1U) || (qo_config.required_good > 10U) ||
            (qo_config.max_consecutive_bad > 10U)) {
            fault = 1;
        }
    }

    if (!fault) {
        for (i = 0U; i < n; i++) {
            adcs_vec3_t tb, tr;
            adcs_vec3_t wp;
            if ((!isfinite(qo_input.weights[i])) || (qo_input.weights[i] <= 0.0) ||
                (!adcs_is_finite_vec3(&qo_input.body[i])) ||
                (!adcs_is_finite_vec3(&qo_input.reference[i])) ||
                (adcs_vec3_normalize(&qo_input.body[i], ADCS_EPS_NORM, &tb) != ADCS_OK) ||
                (adcs_vec3_normalize(&qo_input.reference[i], ADCS_EPS_NORM, &tr) != ADCS_OK)) {
                fault = 1;
                break;
            }
            ub[i] = tb;
            ur[i] = tr;
            wsum += qo_input.weights[i];
            wp = adcs_vec3_scale(&tb, qo_input.weights[i]);
            wbody = adcs_vec3_add(&wbody, &wp);
            align_sum += qo_input.weights[i] * adcs_vec3_dot(&tb, &tr);
            valid_count++;
        }
    }

    if (fault) {
        qo_output.mode = QO_FAULT;
        qo_output.usable = 0U;
        qo_output.total_weight = 0.0;
        qo_output.mean_alignment = 0.0;
        qo_output.body_separation_sine = 0.0;
        qo_output.reference_separation_sine = 0.0;
        qo_output.weighted_body = (adcs_vec3_t){0.0, 0.0, 0.0};
        qo_output.good = qo_state.good;
        return;
    }

    {
        adcs_vec3_t c;
        c = adcs_vec3_cross(&ub[0], &ub[1]);
        bs_sine = adcs_vec3_norm(&c);
        c = adcs_vec3_cross(&ur[0], &ur[1]);
        rs_sine = adcs_vec3_norm(&c);
    }

    if ((wsum >= qo_config.minimum_weight) &&
        (bs_sine >= qo_config.minimum_separation_sine) &&
        (rs_sine >= qo_config.minimum_separation_sine)) {
        usable = 1;
    }

    if (qo_input.enable == 0) {
        qo_state.mode = QO_WAIT;
        qo_state.good = 0U;
        qo_state.bad_streak = 0U;
    } else if (usable) {
        qo_state.bad_streak = 0U;
        qo_state.good = qo_state.good + 1U;
        if (qo_state.good >= qo_config.required_good) {
            qo_state.mode = QO_SOLVE;
        } else {
            qo_state.mode = QO_WAIT;
        }
    } else {
        qo_state.bad_streak = qo_state.bad_streak + 1U;
        if (qo_state.bad_streak > qo_config.max_consecutive_bad) {
            qo_state.mode = QO_WAIT;
            qo_state.good = 0U;
            qo_state.bad_streak = 0U;
        } else {
            qo_state.mode = QO_HOLD;
        }
    }

    qo_output.mode = qo_state.mode;
    qo_output.good = qo_state.good;
    qo_output.usable = usable ? valid_count : 0U;
    qo_output.total_weight = wsum;
    qo_output.mean_alignment = (wsum > 0.0) ? (align_sum / wsum) : 0.0;
    qo_output.body_separation_sine = bs_sine;
    qo_output.reference_separation_sine = rs_sine;
    qo_output.weighted_body = wbody;
}

